import re
from collections import defaultdict
from typing import Callable, Dict, Tuple, List

class NotFound(Exception):
    """Raised when no route matches the requested path."""
    pass

class MethodNotAllowed(Exception):
    """Raised when a route matches the path but not the HTTP method."""
    pass

class Router:
    def __init__(self) -> None:
        # For each method we keep two structures:
        #   - static_routes: mapping from exact path to handler
        #   - param_routes: list of (segments, handler)
        self._static_routes: Dict[str, Dict[str, Callable]] = defaultdict(dict)
        self._param_routes: Dict[str, List[Tuple[List[str], Callable]]] = defaultdict(list)
        # Also keep a set of all patterns for MethodNotAllowed detection
        self._all_patterns: List[Tuple[List[str], str]] = []

    def _normalize(self, path: str) -> str:
        """Remove trailing slash unless path is root."""
        if path != "/" and path.endswith("/"):
            return path[:-1]
        return path

    def _parse_pattern(self, pattern: str) -> List[str]:
        """Split pattern into segments."""
        pattern = self._normalize(pattern)
        return [seg for seg in pattern.split("/") if seg]

    def add(self, method: str, pattern: str, handler: Callable) -> None:
        method = method.upper()
        pattern = self._normalize(pattern)
        segments = self._parse_pattern(pattern)

        # Determine if pattern is static (no parameters)
        if all("{" not in seg and "}" not in seg for seg in segments):
            self._static_routes[method][pattern] = handler
        else:
            self._param_routes[method].append((segments, handler))

        # Store for MethodNotAllowed detection
        self._all_patterns.append((segments, method))

    def _match_static(self, method: str, path: str) -> Tuple[Callable, Dict[str, str]]:
        if path in self._static_routes[method]:
            return self._static_routes[method][path], {}
        raise KeyError

    def _match_param(self, method: str, path_segments: List[str]) -> Tuple[Callable, Dict[str, str]]:
        for segs, handler in self._param_routes[method]:
            if len(segs) != len(path_segments):
                continue
            params: Dict[str, str] = {}
            matched = True
            for pat_seg, path_seg in zip(segs, path_segments):
                if pat_seg.startswith("{") and pat_seg.endswith("}"):
                    name = pat_seg[1:-1]
                    if not path_seg:
                        matched = False
                        break
                    params[name] = path_seg
                else:
                    if pat_seg != path_seg:
                        matched = False
                        break
            if matched:
                return handler, params
        raise KeyError

    def _path_matches_any(self, path_segments: List[str]) -> bool:
        """Return True if any registered pattern matches the path segments."""
        for segs, _ in self._all_patterns:
            if len(segs) != len(path_segments):
                continue
            matched = True
            for pat_seg, path_seg in zip(segs, path_segments):
                if pat_seg.startswith("{") and pat_seg.endswith("}"):
                    if not path_seg:
                        matched = False
                        break
                else:
                    if pat_seg != path_seg:
                        matched = False
                        break
            if matched:
                return True
        return False

    def dispatch(self, method: str, path: str) -> Tuple[Callable, Dict[str, str]]:
        method = method.upper()
        path = self._normalize(path)
        path_segments = [seg for seg in path.split("/") if seg]

        # 1. Try static route
        try:
            return self._match_static(method, path)
        except KeyError:
            pass

        # 2. Try parameter route
        try:
            return self._match_param(method, path_segments)
        except KeyError:
            pass

        # 3. Check if any route matches path (for MethodNotAllowed)
        if self._path_matches_any(path_segments):
            raise MethodNotAllowed(f"Method {method} not allowed for path {path}")

        # 4. No match
        raise NotFound(f"No route matches path {path}")
